import UIKit
import CoreText

/// The fake CryptoBot's typeface. The real mini app is set in Inter (the page is a web page), so the
/// copy uses it too: four weights, cut down to Latin and Cyrillic, are embedded here as base64 and
/// registered with Core Text on first use. Inter is licensed under the SIL Open Font License 1.1
/// (https://openfontlicense.org), which allows exactly this. If registration fails the system font
/// stands in.
enum PampGramFakeCryptoBotFonts {
    private static var names: [String: String] = [:]
    private static var registered = false

    private static func registerIfNeeded() {
        if self.registered {
            return
        }
        self.registered = true
        for (key, encoded) in self.table {
            guard let data = Data(base64Encoded: encoded), let provider = CGDataProvider(data: data as CFData), let font = CGFont(provider) else {
                continue
            }
            if let name = font.postScriptName as String? {
                self.names[key] = name
            }
            var error: Unmanaged<CFError>?
            _ = CTFontManagerRegisterGraphicsFont(font, &error)
        }
    }

    /// `tabular` asks for digits of equal width (the rolling balance needs them).
    static func font(_ size: CGFloat, _ weight: UIFont.Weight, tabular: Bool = false) -> UIFont {
        self.registerIfNeeded()
        var key = "regular"
        if weight == .medium {
            key = "medium"
        } else if weight == .semibold {
            key = "semibold"
        } else if weight == .bold || weight == .heavy || weight == .black {
            key = "bold"
        }
        guard let name = self.names[key], let base = UIFont(name: name, size: size) else {
            return tabular ? UIFont.monospacedDigitSystemFont(ofSize: size, weight: weight) : UIFont.systemFont(ofSize: size, weight: weight)
        }
        if !tabular {
            return base
        }
        let features: [[UIFontDescriptor.FeatureKey: Any]] = [[
            UIFontDescriptor.FeatureKey(rawValue: "CTFeatureTypeIdentifier"): 6,
            UIFontDescriptor.FeatureKey(rawValue: "CTFeatureSelectorIdentifier"): 0
        ]]
        let descriptor = base.fontDescriptor.addingAttributes([UIFontDescriptor.AttributeName.featureSettings: features])
        return UIFont(descriptor: descriptor, size: size)
    }

    private static let table: [String: String] = [
        "regular": "",
        "medium": "",
        "semibold": "",
        "bold": ""
    ]
}
